    /**
     * Method to retrieve the Contract via ContractFetchOneSummary
     * @param 	summary ContractFetchOneSummary 
     * @return 	ContractFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Contract getContract( ContractFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ContractFetchOneSummary arg cannot be null" );
    	
    	Contract entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Contract
        	// --------------------------------------
        	CompletableFuture<Contract> futureEntity = queryGateway.query(new FindContractQuery( new LoadContractFilter( summary.getContractId() ) ), ResponseTypes.instanceOf(Contract.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Contract with id " + summary.getContractId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


